/*
 * The published URL form, in one place.
 *
 * Hand-written, deliberately: src/site.ts is generated by scripts/html-to-jsx.mjs
 * and gets overwritten, so the rules that decide how a page is *addressed* live
 * here instead. Every component that links to a page, and head() in server.tsx,
 * go through these functions rather than spelling out a filename.
 *
 * The form is extensionless and relative — `technology`, not `technology.html`
 * and not `/technology`.
 *
 * Extensionless works because GitHub Pages appends `.html` when a request path
 * has no extension, so /technology and /technology.html return the same bytes.
 * The files on disk keep their suffix; only the addresses lose it.
 *
 * Relative rather than root-absolute because this repository answers to two
 * hostnames — www.r4space.com at the domain root, and Ravan14.github.io/R4 one
 * level down. `/technology` is correct on the first and a 404 on the second;
 * `technology` is correct on both.
 */

import { PAGES, type PageKey } from './site.ts';

/** The canonical host. Canonical URLs must be absolute; nothing else here is. */
export const ORIGIN = 'https://www.r4space.com';

/**
 * Turn a published filename, optionally with a fragment, into the address a
 * visitor should see: 'technology.html#analytics' -> 'technology#analytics',
 * 'index.html' -> './'.
 */
export function hrefFor(file: string): string {
  const hash = file.indexOf('#');
  const path = hash === -1 ? file : file.slice(0, hash);
  const fragment = hash === -1 ? '' : file.slice(hash);
  if (path === 'index.html') return `./${fragment}`;
  return `${path.replace(/\.html$/i, '')}${fragment}`;
}

/** The relative address of a page, for use in an href. */
export function urlFor(key: PageKey): string {
  return hrefFor(PAGES[key].file);
}

/**
 * The absolute canonical address of a page. Home is the bare origin with a
 * trailing slash, because that is the form the sitemap carries and the form
 * the root document actually is — /, /index and /index.html are the same page
 * and this says which one search engines should keep.
 */
export function canonicalFor(key: PageKey): string {
  const file = PAGES[key].file;
  if (file === 'index.html') return `${ORIGIN}/`;
  return `${ORIGIN}/${file.replace(/\.html$/i, '')}`;
}
